import {COMMERCIAL_SECTORS as SECTORS,COMMERCIAL_INTERESTS as INTERESTS} from './commercial-schema.js';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const params=new URL(location.href).searchParams,preview=params.get('preview'),slug=params.get('id')||'',root=document.querySelector('#main');
const steps=[['01','Envie o que você já tem','Fotos, vídeos, identidade e um pedido com objetivo e formato. Você pode começar no portal; o WhatsApp precisa estar vinculado.'],['02','Acompanhe e revise','A criação passa pelo processamento. Confira a prévia e solicite ajustes; um pedido na fila ainda não é uma entrega pronta.'],['03','Escolha como publicar','Baixe o arquivo e publique. Se contratar publicação assistida, a equipe revisa a versão, obtém sua aprovação e registra a postagem manual.']];
async function load(){try{const response=await fetch(preview?'/api/portal/commercial-preview?id='+encodeURIComponent(preview):'/api/presentations/'+encodeURIComponent(slug));const p=await response.json();if(!response.ok)throw new Error('Esta apresentação não está disponível. Peça um link atualizado à Helpu.');document.title=(p.company||SECTORS[p.sector].name)+' · Helpu';
  root.innerHTML=`${preview?'<aside class="public-context"><strong>Prévia restrita da equipe</strong><p>Revise este rascunho. Ele ainda não substitui a versão do link público.</p></aside>':''}<section class="present-hero"><div><p class="eyebrow">HELPU PARA ${esc(SECTORS[p.sector].name.toUpperCase())}</p>${p.company?`<p class="personal">Uma conversa com ${esc(p.company)}.</p>`:''}<h1>${esc(p.headline)}</h1><p class="hero-copy">${esc(p.problem)}</p><a class="button orange" href="#interesse">Escolher o que preciso <span>↘</span></a><p class="small">Criação com IA e acompanhamento humano, conforme o serviço contratado.</p></div><figure class="brand-film"><video controls muted playsinline preload="none" poster="assets/helpu-motion-poster.webp" src="assets/helpu-motion.mp4" aria-label="Vídeo da identidade Helpu"></video><figcaption>Conheça a identidade Helpu · filme da marca.</figcaption></figure></section>
  ${p.context?`<aside class="public-context"><p class="eyebrow">PONTO DE PARTIDA</p><p>${esc(p.context)}</p><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Contexto público conferido em ${esc(p.checkedAt.split('-').reverse().join('/'))} ↗</a><p class="small">Esta observação inicia a conversa. Não é um diagnóstico completo da empresa.</p></aside>`:''}
  <section class="present-section"><p class="eyebrow">APLICAÇÕES PARA SUA ROTINA</p><h2>Uma boa ideia precisa ganhar forma.</h2><p class="section-copy">${esc(p.application)}</p>${p.media.length?`<div class="example-grid">${p.media.map(a=>`<figure class="example">${a.mime==='video/mp4'?`<video controls playsinline preload="none" src="${esc(a.url)}" aria-label="${esc(a.caption)}"></video>`:`<img loading="lazy" src="${esc(a.url)}" alt="${esc(a.caption)}">`}<figcaption><span class="example-label">${a.mode==='real'?'Material real · uso autorizado':'Demonstração ilustrativa'}</span><p>${esc(a.caption)}</p></figcaption></figure>`).join('')}</div>`:'<p class="empty-example">Conte qual material você já tem. A equipe poderá apresentar exemplos adequados ao seu pedido antes da contratação.</p>'}<p class="small">Os exemplos mostram formatos e apresentação. Não representam garantia de alcance, vendas ou outros resultados comerciais.</p></section>
  <section class="present-section workflow"><div><p class="eyebrow">DO MATERIAL À ENTREGA</p><h2>Você participa das decisões.</h2><p>Explore as etapas para entender o que acontece com seu pedido.</p></div><div><div class="step-tabs" role="group" aria-label="Etapas do atendimento">${steps.map(([n,title],i)=>`<button type="button" data-step="${i}" aria-pressed="${i===0}">${n} · ${title}</button>`).join('')}</div><article id="step-detail" aria-live="polite"></article></div></section>
  <section id="interesse" class="present-section interest-section"><div><p class="eyebrow">SEU PRÓXIMO PASSO</p><h2>O que faz sentido para você agora?</h2><p>Selecione suas necessidades. A equipe retorna pelo canal escolhido para combinar escopo, proposta ou uma conversa.</p><p class="small">Sem contratação ou cobrança neste formulário. Valores e condições serão apresentados antes do aceite.</p></div><form id="interest-form"><fieldset><legend>Quero saber mais sobre</legend>${Object.entries(INTERESTS).map(([k,v])=>`<label class="interest-option"><input name="interests" value="${k}" type="checkbox"><span>${v}</span></label>`).join('')}</fieldset><div class="form-grid"><label>Seu nome<input name="name" autocomplete="name" required maxlength="100"></label><label>Empresa<input name="company" autocomplete="organization" value="${esc(p.company)}" required maxlength="120"></label></div><label>E-mail<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>Prefiro receber o retorno por<select name="channel"><option value="email">E-mail</option><option value="whatsapp">WhatsApp</option></select></label><label id="phone-field" hidden>WhatsApp com DDD<input name="phone" type="tel" autocomplete="tel" maxlength="30"></label><label>O que você gostaria de resolver? (opcional)<textarea name="note" maxlength="1500" rows="3"></textarea></label><label class="trap" aria-hidden="true">Site<input name="website" tabindex="-1" autocomplete="off"></label><label class="interest-option consent"><input name="consent" type="checkbox" required><span>Autorizo a Helpu a retornar pelo canal escolhido sobre esta solicitação. Isso não autoriza campanhas ou envios em massa. <a href="/privacidade.html" target="_blank" rel="noopener">Como meus dados são tratados</a>.</span></label><p id="interest-status" role="status"></p><button class="button orange" type="submit">Solicitar uma conversa <span>↗</span></button></form></section>`;
  function selectStep(i){root.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===i)));const[n,title,body]=steps[i];document.querySelector('#step-detail').innerHTML=`<span class="step-number">${n}</span><h3>${title}</h3><p>${body}</p>`;}
  root.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>selectStep(Number(b.dataset.step))));selectStep(0);
  const form=document.querySelector('#interest-form');if(preview){form.innerHTML='<h3>Prévia do próximo passo</h3><p>Após liberar o link público, o visitante poderá escolher suas necessidades e solicitar retorno por e-mail ou WhatsApp.</p>';return;}form.elements.channel.addEventListener('change',()=>{const phone=form.elements.channel.value==='whatsapp';document.querySelector('#phone-field').hidden=!phone;form.elements.phone.required=phone;});let sending=false,key=crypto.randomUUID();form.addEventListener('submit',async e=>{e.preventDefault();if(sending)return;const status=document.querySelector('#interest-status'),fields=new FormData(form),interests=fields.getAll('interests');if(!interests.length){status.textContent='Escolha pelo menos uma necessidade.';return;}sending=true;const button=form.querySelector('button');button.disabled=true;status.textContent='Registrando seu interesse…';try{const response=await fetch('/api/presentations/'+encodeURIComponent(slug)+'/interest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(fields),interests,consent:fields.get('consent')==='on',requestKey:key})});const value=await response.json();if(!response.ok)throw new Error(value.error||'Não foi possível registrar. Tente novamente.');form.innerHTML='<div class="interest-success" role="status"><p class="eyebrow">SOLICITAÇÃO RECEBIDA</p><h3>Vamos conversar sobre seu próximo passo.</h3><p>A equipe recebeu suas escolhas e os dados para retorno. Aguarde o contato pelo canal informado.</p><p>Se já tem uma conta, suas propostas privadas ficam em <strong>Minha empresa → Propostas</strong>.</p><a class="button" href="/entrar.html">Entrar no portal ↗</a></div>';}catch(error){status.textContent=error.message;button.disabled=false;sending=false;}});
}catch(e){root.innerHTML=`<section class="present-section"><h1>Vamos retomar esta conversa.</h1><p role="alert">${esc(e.message)}</p><a class="button orange" href="/">Conhecer a Helpu</a></section>`;}}
load();
